import React, { useState, useEffect } from 'react';
import { AuthProvider } from './context/AuthContext';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import Catalog from './pages/Catalog';
import ProductPage from './pages/ProductPage';
import Profile from './pages/Profile';
import Auth from './pages/Auth';

function App() {
  const [currentPage, setCurrentPage] = useState('home');

  // ✅ Добавьте этот useEffect для отслеживания хэша
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '');
      console.log('Current hash:', hash); // Для отладки

      if (hash && ['catalog', 'product', 'profile', 'auth'].includes(hash)) {
        setCurrentPage(hash);
      } else {
        setCurrentPage('home');
      }
    };

    // Слушаем изменения хэша
    window.addEventListener('hashchange', handleHashChange);

    // Проверяем начальный хэш
    handleHashChange();

    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  // Функция навигации
  const navigate = (page) => {
    setCurrentPage(page);
    window.location.hash = page;
  };

  // Рендер текущей страницы
  const renderPage = () => {
    console.log('Rendering page:', currentPage); // Для отладки

    switch (currentPage) {
      case 'catalog':
        return <Catalog />;
      case 'product':
        return <ProductPage />;
      case 'profile':
        return <Profile />;
      case 'auth':
        return <Auth />;
      default:
        return <Home />;
    }
  };

  return (
    <AuthProvider>
      <div className="min-h-screen bg-white">
        <Navbar onNavigate={navigate} />
        {renderPage()}
        <Footer />
      </div>
    </AuthProvider>
  );
}

export default App;
